import{_ as t,o,c as d,ag as r}from"./chunks/framework.CVaJrGn7.js";const h=JSON.parse('{"title":"@guideflow/react","description":"@guideflow/react — React hooks and components for GuideFlow product tours. TourProvider, useTour(), useTourStep(), useHotspot(), TourStep, HotspotBeacon.","frontmatter":{"description":"@guideflow/react — React hooks and components for GuideFlow product tours. TourProvider, useTour(), useTourStep(), useHotspot(), TourStep, HotspotBeacon.","keywords":"@guideflow/react, React product tour hooks, useTour hook, TourProvider component, React onboarding","head":[["link",{"rel":"canonical","href":"https://realnerdzw.github.io/GuideFlow/packages/react"}],["meta",{"property":"og:url","content":"https://realnerdzw.github.io/GuideFlow/packages/react"}],["meta",{"property":"og:title","content":"@guideflow/react — GuideFlow.js"}],["meta",{"property":"og:description","content":"@guideflow/react — React hooks and components for GuideFlow product tours. TourProvider, useTour(), useTourStep(), useHotspot(), TourStep, HotspotBeacon."}],["meta",{"name":"twitter:title","content":"@guideflow/react — GuideFlow.js"}],["meta",{"name":"twitter:description","content":"@guideflow/react — React hooks and components for GuideFlow product tours. TourProvider, useTour(), useTourStep(), useHotspot(), TourStep, HotspotBeacon."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Packages\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/packages/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"React\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/packages/react/\\"}]}"]]},"headers":[],"relativePath":"packages/react.md","filePath":"packages/react.md","lastUpdated":1785506067000}'),a={name:"packages/react.md"};function c(s,e,i,n,p,u){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="guideflow-react" tabindex="-1">@guideflow/react <a class="header-anchor" href="#guideflow-react" aria-label="Permalink to &quot;@guideflow/react&quot;">​</a></h1><p><strong>React hooks and components for GuideFlow product tours.</strong></p><p><a href="https://www.npmjs.com/package/@guideflow/react" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/v/@guideflow/react.svg" alt="npm version"></a></p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @guideflow/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @guideflow/react</span></span></code></pre></div><h2 id="key-exports" tabindex="-1">Key exports <a class="header-anchor" href="#key-exports" aria-label="Permalink to &quot;Key exports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Export</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>TourProvider</code></td><td>Component</td><td>Shares a <code>GuideFlowInstance</code> through context</td></tr><tr><td><code>useGuideFlow()</code></td><td>Hook</td><td>Returns the instance; throws outside a provider</td></tr><tr><td><code>useTour(flowId?)</code></td><td>Hook</td><td>Tour state (<code>isActive</code>, <code>isPaused</code>, <code>currentStepId</code>, <code>currentStepIndex</code>, <code>totalSteps</code>) plus <code>start</code> / <code>next</code> / <code>prev</code> / <code>goTo</code> / <code>send</code> / <code>stop</code> / <code>pause</code> / <code>resume</code> / <code>skip</code></td></tr><tr><td><code>useTourStep(stepId)</code></td><td>Hook</td><td><code>{ ref, isActive }</code> — is this step active right now</td></tr><tr><td><code>useHotspot(ref, options)</code></td><td>Hook</td><td>Attaches a pulsing beacon to a ref for the component&#39;s lifetime</td></tr><tr><td><code>TourStep</code></td><td>Component</td><td>Renders its children only while a named step is active</td></tr><tr><td><code>HotspotBeacon</code></td><td>Component</td><td>Selector-targeted beacon; renders <code>null</code></td></tr><tr><td><code>ConversationalPanel</code></td><td>Component</td><td>Floating AI chat panel (needs <code>@guideflow/ai</code> on the instance)</td></tr><tr><td><code>GuidePopover</code></td><td>Component</td><td>The React-rendered popover — needs <a href="/GuideFlow/api/react/guide-popover"><code>renderer=&quot;react&quot;</code></a></td></tr><tr><td><code>createHeadlessRenderer()</code></td><td>Function</td><td>A <code>RendererContract</code> that reports steps to React instead of drawing them</td></tr><tr><td><code>useTourRenderer()</code></td><td>Hook</td><td>The provider&#39;s headless renderer, for building your own popover</td></tr></tbody></table><p>The package also re-exports the core types <code>FlowDefinition</code>, <code>Step</code>, <code>StepContent</code>, <code>GuidanceContext</code>, <code>HotspotOptions</code>, <code>HintStep</code>, <code>GuideFlowConfig</code> and <code>PopoverPlacement</code>, plus its own prop types (<code>TourProviderProps</code>, <code>TourStepProps</code>, <code>GuidePopoverProps</code>, <code>HotspotBeaconProps</code>, <code>ConversationalPanelProps</code>, <code>UseTourReturn</code>, <code>TourState</code>, <code>UseTourStepReturn</code>, <code>UseHotspotReturn</code>, <code>Message</code>).</p><p>By default the popover and spotlight you see during a tour are drawn by <code>@guideflow/core</code>&#39;s renderer, and none of the components in this package are required to run a tour. Set <a href="/GuideFlow/api/react/tour-provider#choosing-who-draws-the-popover"><code>&lt;TourProvider renderer=&quot;react&quot;&gt;</code></a> to move the popover into React instead — then <code>&lt;GuidePopover&gt;</code> is required. The spotlight belongs to the engine either way.</p><h2 id="peer-dependencies" tabindex="-1">Peer dependencies <a class="header-anchor" href="#peer-dependencies" aria-label="Permalink to &quot;Peer dependencies&quot;">​</a></h2><ul><li><code>react</code> ^18.0.0 || ^19.0.0</li><li><code>react-dom</code> ^18.0.0 || ^19.0.0</li></ul><p>React 17 is not supported — the adapter uses <code>useId</code> and <code>useSyncExternalStore</code>.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://www.npmjs.com/package/@guideflow/react" target="_blank" rel="noreferrer">npm</a></li><li><a href="https://github.com/RealNerdZW/GuideFlow/tree/master/packages/react" target="_blank" rel="noreferrer">Source</a></li><li><a href="/GuideFlow/guide/react">React Guide</a></li><li><a href="/GuideFlow/api/react/tour-provider">API Reference</a></li></ul>',14)])])}const g=t(a,[["render",c]]);export{h as __pageData,g as default};
